CREATE TABLE whatsapp_ads (id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, user_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, ad_id VARCHAR(64) NOT NULL, name VARCHAR(160) NOT NULL, offer_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, status VARCHAR(10) NOT NULL DEFAULT 'active', origin VARCHAR(16) NOT NULL, source JSON NOT NULL, first_seen_at DATETIME(6) NULL, last_seen_at DATETIME(6) NULL, created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6), PRIMARY KEY (id), UNIQUE KEY whatsapp_ads_ad_uq (user_id,ad_id), UNIQUE KEY whatsapp_ads_owner_uq (id,user_id), CONSTRAINT whatsapp_ads_status_ck CHECK (status IN ('active','paused')), CONSTRAINT whatsapp_ads_origin_ck CHECK (origin IN ('first_message','manual')), CONSTRAINT whatsapp_ads_user_fk FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci